    { izvorno: "Dov'è il bagno?", izgovor: "do-VE il BA-njo", hr: "Gdje je toalet?" },
    { izvorno: "Era buonissimo!", izgovor: "E-ra buo-NIS-si-mo", hr: "Bilo je izvrsno!" }
