        { ime: "Katakombe svetog Januarija", opis: "Ako želite vidjeti ranokršćanski Napulj, pođite u katakombe u četvrti Sanità, široke poput podzemnih bazilika. Vode ih mladi iz četvrti okupljeni u zadrugu, koja je time oživjela cijeli kvart.", link: "https://catacombedinapoli.it/en/" },
        { ime: "Uspon na krater Vezuva", opis: "Ako želite pogledati u vulkan, autobusom ili automobilom dođite do parkirališta na tisuću metara, odakle do ruba kratera vodi polusatna staza. Ulaznice se kupuju unaprijed putem interneta.", link: "https://www.parconazionaledelvesuvio.it/en/" },
        { ime: "Podzemni obilazak", opis: "Ako vas ne smetaju uski prolazi, pridružite se vođenom obilasku grčko-rimskog podzemlja s ulazom na Piazzi San Gaetano.", link: "https://www.napolisotterranea.org/en/" }
