        { ime: "Šetnja uz uličnu hranu", opis: "Ako se same ne usudite naručiti slezenu, pridružite se vođenoj šetnji po tržnicama s kušanjima.", link: "https://www.palermostreetfood.com/" },
        { ime: "Kazalište lutaka", opis: "Ako želite vidjeti sicilijanski običaj pod zaštitom UNESCO-a, pogledajte predstavu opere dei pupi, u kojoj velike drvene lutke u oklopima igraju viteške bitke Karla Velikog. Međunarodni muzej lutaka ima zbirku i redovite predstave.", link: "https://www.museodellemarionette.it/" },
        { ime: "Palermo bez mafije", opis: "Ako želite čuti kako se grad opire reketu, pođite na šetnju udruge Addiopizzo, koja vodi kroz mjesta važna za borbu protiv mafije i u lokale koji javno odbijaju plaćati reket.", link: "https://www.addiopizzotravel.it/en/" }
